items.freemarker:
[#import "/ui/ui.ftl" as ui]
[@ui.accordion default="a" items=[
  {"value":"a", "title":"რა არის Despani?", "content":"<p>პორტალი.</p>"},
  {"value":"b", "title":"Colibri UI?", "content":"<p>Headless UI.</p>"}
]/]

[#import "/ui/ui.ftl" as ui]
[@ui.dropdown kind="context-menu" trigger="Right-click here" items=[
  {"label":"Back"}, {"label":"Reload"}, {"type":"separator"},
  {"label":"Show bookmarks", "type":"checkbox"}
]/]

[#import "/ui/ui.ftl" as ui]
[@ui.breadcrumb crumbs=[
  {"label":"მთავარი", "href":"/"},
  {"label":"სტატიები", "href":"/articles"},
  {"label":"რედაქტირება"}
]/]

[#import "/ui/ui.ftl" as ui]
[@ui.menubar label="App" menus=[
  {"label":"ფაილი", "items":[{"label":"ახალი"}, {"label":"გახსნა…"}, {"type":"separator"}, {"label":"ბეჭდვა"}]},
  {"label":"რედაქტირება", "items":[{"label":"Undo"}, {"label":"Redo"}]}
]/]

[#import "/ui/ui.ftl" as ui]
[@ui.stepper linear=true back="უკან" next="შემდეგი" finish="დასრულება" steps=[
  {"label":"ანგარიში", "content":"<label>ელ-ფოსტა <input type='email' name='email' required></label>"},
  {"label":"პროფილი", "content":"<label>სახელი <input name='name'></label>"},
  {"label":"დასრულება", "content":"მზადაა!"}
]/]

[#import "/ui/ui.ftl" as ui]
[@ui.dialog trigger="Command palette" title="Command"]
  [@ui.command hotkey="k" groups=[
    {"label":"გვერდები", "options":[{"value":"home","label":"მთავარი","keywords":"main"}, {"value":"articles","label":"სტატიები"}]}
  ]/]
[/@ui.dialog]

[#import "/ui/ui.ftl" as ui]
[@ui.radioGroup name="lang" value=form.lang label="Language" options=[
  {"value":"ka", "label":"ქართული"}, {"value":"en", "label":"English"}
]/]

[#import "/ui/ui.ftl" as ui]
[@ui.select name="lang" value=form.lang placeholder="აირჩიეთ ენა" groups=[
  {"label":"ევროპა", "options":[{"value":"ka","label":"ქართული"}, {"value":"en","label":"English"}]}
]/]
[@ui.select name="tags" multiple=true placeholder="ტეგები" options=tagOptions/]

[#import "/ui/ui.ftl" as ui]
[@ui.combobox name="city" placeholder="ქალაქი…" label="City" options=[
  {"value":"tbilisi","label":"თბილისი"}, {"value":"batumi","label":"ბათუმი"}
]/]
[@ui.combobox name="langs" multiple=true allowCustom=true options=langOptions/]

[#import "/ui/ui.ftl" as ui]
[@ui.sortable name="order" label="Order" items=[
  {"value":"a","label":"ერთი"}, {"value":"b","label":"ორი"}, {"value":"c","label":"სამი"}
]/]

[#import "/ui/ui.ftl" as ui]
[@ui.toggleGroup type="single" value="c" label="Align" items=[
  {"value":"l","label":"L"}, {"value":"c","label":"C"}, {"value":"r","label":"R"}
]/]

[#import "/ui/ui.ftl" as ui]
<link rel="stylesheet" href="/ui/themes/motion.css">
<div data-ui-motion="slide-up">…appears with slide-up, exits the same way…</div>
<div data-ui-motion="fade" data-ui-motion-exit="collapse" data-ui-motion-speed="slow">…</div>
[#-- register your own (CSS): --]
<style>
  @keyframes ui-swing-in { from { opacity:0; transform:rotate(-12deg) } }
  @keyframes ui-swing-out { to { opacity:0; transform:rotate(10deg) } }
  [data-ui-motion=swing] { --ui-motion-in:ui-swing-in; --ui-motion-out:ui-swing-out }
</style>

[#import "/ui/ui.ftl" as ui]
<script type="module">
  import { play } from "@colibri/ui/core/motion";
  form.addEventListener("submit", (e) => { if (!form.checkValidity()) { e.preventDefault(); play(form, "shake"); } });
</script>

[#import "/ui/ui.ftl" as ui]
<link rel="stylesheet" href="/ui/themes/colibri.css">
<style>
  :root {
    --ui-primary: #0f766e; --ui-primary-foreground: #fff;
    --ui-radius: 6px; --ui-font: "Noto Sans Georgian", system-ui, sans-serif;
  }
  html[data-theme=dark] { --ui-primary: #2dd4bf; --ui-primary-foreground: #042f2e; }
</style>
<html data-ui-theme="blue">  [#-- built-in accents: blue green rose orange violet --]
